#let benchmark_results_table() = {
  let data = bench_data()
  let meta = data.meta
  let dirty_tag = if "dirty" in meta and meta.dirty { [ · 수정된 작업 트리] } else { [] }
  let rows = benchmark_rows().map(((label, sub, wl, has_model)) => {
    let sib = bench_find(data, "sibuna", sub, wl)
    let model = none
    (
      [#label],
      [#fmt_ns(if sib != none { sib.ns_per_op_median } else { none })],
      [#fmt_ns(if sib != none { sib.ns_per_op_min } else { none }) – #fmt_ns(if sib != none { sib.ns_per_op_max } else { none })],
      [#fmt_int(if sib != none { sib.ops_per_sec } else { none })],
    )
  }).flatten()
  let naive = bench_find(data, "sibuna-naive", "bot_matcher", "sequential_substring_40_signatures")
  let ac = bench_find(data, "sibuna", "bot_matcher", "aho_corasick_40_signatures")
  [
    #text(size: 8pt, fill: gray)[
      기록일 #meta.date · #meta.host · #meta.cpu · #meta.os · 리비전
      #raw(meta.git)#dirty_tag · Zig #meta.zig · ReleaseFast · 7개 배치의 중앙값과 최솟값–최댓값 범위
    ]
    #v(6pt)
    #grid(
      columns: (1fr, 1fr, 1fr, 1fr),
      gutter: 6pt,
      stat_tile([#fmt_ns(bench_find(data, "sibuna", "pow_verify", "hashcash_16_bits").ns_per_op_median)], [Hashcash 검증],
        [하드웨어 SHA-256, 메모리 할당 없음], fill: blue_light, stroke: blue),
      stat_tile([#fmt_ns(bench_find(data, "sibuna", "token_auth", "blake3_mac_token").ns_per_op_median)], [세션 토큰 검사],
        [키 기반 BLAKE3, 75자 쿠키], fill: green_light, stroke: green),
      stat_tile([#calc.round(meta.idle_rss_kb / 1024, digits: 1) MiB], [유휴 상주 메모리],
        [데몬 시작 후, 저장소 비활성화], fill: amber_light, stroke: amber),
      stat_tile([#calc.round(meta.binary_bytes / 1048576, digits: 1) MiB], [데몬 바이너리],
        [WASM 솔버 #meta.wasm_bytes 바이트], fill: rgb("f5f3ff"), stroke: rgb("7c3aed")),
    )
    #v(8pt)
    #block(width: 100%, inset: 10pt, radius: 5pt, fill: blue_light, stroke: 0.5pt + rule)[
      #text(size: 11pt, weight: "bold")[작업당 실측 지연 시간]
      #linebreak()
      #text(size: 8pt, fill: gray)[기본 연산의 실측 지연 시간만 표시합니다. 메모리 할당 활동은 계측하지 않았습니다.]
      #v(5pt)
      #table(
        columns: (1.6fr, 0.8fr, 1fr, 0.8fr),
        table.header([*워크로드*], [*중앙값*], [*범위*], [*ops/s*]),
        ..rows,
      )
      #v(4pt)
      #text(size: 8pt, fill: gray)[비교를 위해, 이 호스트에서 같은 봇 시그니처 40개를 순차 부분 문자열 검색으로 검사하면 #fmt_ns(naive.ns_per_op_median), 오토마타로 검사하면 #fmt_ns(ac.ns_per_op_median)이 걸립니다.]
    ]
  ]
}

